4	 * Computes the Luhn check digit over the decimal digits contained in a string,
5	 * ignoring any non-digit characters. Used to derive an owner's check digit from its
6	 * customer code.
7	 */
8	public final class Luhn {
9	
10	    private Luhn() {
11	    }
12	
13	    /**
14	     * The Luhn check digit (0-9) over the digits contained in {@code value}; non-digit
15	     * characters are ignored and a {@code null} value is treated as containing no digits.
16	     */
17	    public static int checkDigit(String value) {
18	        if (value == null) {
19	            return 0;
20	        }
21	        int sum = 0;
22	        boolean doubling = true;
23	        for (int i = value.length() - 1; i >= 0; i--) {
24	            char c = value.charAt(i);
25	            if (c < '0' || c > '9') {
26	                continue;
27	            }
28	            int digit = c - '0';
29	            if (doubling) {
30	                digit *= 2;
31	                if (digit > 9) {
32	                    digit -= 9;
33	                }
34	            }
35	            sum += digit;
36	            doubling = !doubling;
37	        }
38	        return (10 - (sum % 10)) % 10;
39	    }
40	}
