3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Computes the SHA-256 digest of a string as hexadecimal. Shared by the derived identities that
9	 * hash owner attributes: the customer code and household id use the upper-case {@link #hex} form,
10	 * the identity key the lower-case {@link #lowerHex} form.
11	 */
12	public final class Sha256 {
13	
14	    private Sha256() {
15	    }
16	
17	    /** The full upper-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
18	    public static String hex(String value) {
19	        return digestHex(value, "%02X");
20	    }
21	
22	    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value} (64 characters). */
23	    public static String lowerHex(String value) {
24	        return digestHex(value, "%02x");
25	    }
26	
27	    private static String digestHex(String value, String byteFormat) {
28	        byte[] digest;
29	        try {
30	            digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
31	        } catch (NoSuchAlgorithmException e) {
32	            throw new IllegalStateException("SHA-256 unavailable", e);
33	        }
34	        StringBuilder hex = new StringBuilder(digest.length * 2);
35	        for (byte b : digest) {
36	            hex.append(String.format(byteFormat, b));
37	        }
38	        return hex.toString();
39	    }
40	}
