3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year arithmetic for date-derived values. The fiscal year starts on 1 July and is
8	 * named for the calendar year in which it ends: a date on or after 1 July belongs to the
9	 * fiscal year ending the following calendar year, while an earlier date belongs to the fiscal
10	 * year ending in its own calendar year (e.g. both 2025-08-01 and 2026-03-01 fall in FY26).
11	 */
12	public final class FiscalYear {
13	
14	    /** The month a fiscal year starts (1 July). */
15	    private static final int START_MONTH = Month.JULY.getValue();
16	
17	    private FiscalYear() {
18	    }
19	
20	    /** The calendar year in which the fiscal year containing {@code date} ends. */
21	    public static int of(LocalDate date) {
22	        return (date.getMonthValue() >= START_MONTH) ? date.getYear() + 1 : date.getYear();
23	    }
24	
25	    /** The two-digit fiscal year for {@code date} (e.g. {@code 26} for FY26). */
26	    public static int twoDigit(LocalDate date) {
27	        return of(date) % 100;
28	    }
29	
30	    /** The fiscal year label {@code FY<YY>} for {@code date} (e.g. {@code "FY26"}). */
31	    public static String label(LocalDate date) {
32	        return String.format("FY%02d", twoDigit(date));
33	    }
34	
35	    /** Whole fiscal years elapsed from {@code from} to {@code to}. */
36	    public static int elapsedBetween(LocalDate from, LocalDate to) {
37	        return of(to) - of(from);
38	    }
39	}
