7	/**
8	 * Assigns a newly built owner its {@code membershipNumber}, formatted
9	 * {@code <customerCode>-M<YY>}, where YY is the two-digit fiscal year (starting 1 July) of
10	 * the business-day-adjusted registration date (e.g. {@code NSW-1A2B3C4D-M26}). Runs after
11	 * both the customer code and the registration date have been assigned, so both inputs are
12	 * present.
13	 */
14	public class AssignMembershipNumber {
15	
16	    public void service(@Val Owner owner) {
17	        int yy = FiscalYear.twoDigit(owner.getRegistrationDate());
18	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
19	    }
20	}
