17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String unique = CustomerCode.deduplicate(owner.getCustomerCode(),
20	                code -> !ownerRepository.findByCustomerCode(code).isEmpty());
21	        owner.setCustomerCode(unique);
22	    }
23	}
