3	/**
4	 * Classifies an owner into a market segment formatted {@code <TIER>_<AREA>}, one of
5	 * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
6	 * {@code "STANDARD_REGIONAL"}. TIER is {@code "PREMIUM"} when the membership level is 3 or more,
7	 * otherwise {@code "STANDARD"}. AREA is {@code "METRO"} when the locality is a known region (see
8	 * {@link CityRegion}), otherwise {@code "REGIONAL"}. Used to derive an owner's segment from its
9	 * membership level and locality.
10	 */
11	public final class OwnerSegment {
12	
13	    private OwnerSegment() {
14	    }
15	
16	    /**
17	     * The segment of an owner with membership {@code level} and {@code locality}. A {@code null}
18	     * level is treated as below the PREMIUM threshold; a {@code null} or {@link CityRegion#UNKNOWN}
19	     * locality as not a known region.
20	     */
21	    public static String classify(Integer level, String locality) {
22	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
23	        boolean knownRegion = locality != null && !CityRegion.UNKNOWN.equals(locality);
24	        String area = knownRegion ? "METRO" : "REGIONAL";
25	        return tier + "_" + area;
26	    }
27	}
