3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	import tools.jackson.databind.ObjectMapper;
9	
10	/**
11	 * Emits the immutable {@link OwnerCreatedEvent} as a single JSON line on the {@code AUDIT} logger, in
12	 * addition to the human-readable line from {@link AuditOwnerCreated}. Runs after {@link SaveOwner} so
13	 * the owner id is assigned, and draws its sequence number from {@link AuditSequence} so events are
14	 * totally ordered across creates.
15	 */
16	public class EmitOwnerCreatedEvent {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    private static final ObjectMapper JSON = new ObjectMapper();
21	
22	    public void service(@Val Owner owner, AuditSequence sequence) {
23	        OwnerCreatedEvent event = OwnerCreatedEvent.of(sequence.next(), owner);
24	        AUDIT.info(JSON.writeValueAsString(event));
25	    }
26	}
