3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.stereotype.Component;
6	
7	/**
8	 * Supplies the monotonically increasing sequence numbers stamped on audit events, so events can be
9	 * totally ordered across owner creates.
10	 *
11	 * <p>Deliberately in-memory and non-transactional (like {@link IdempotencyStore}): the counter must
12	 * advance once per emitted event and never roll back with the request that consumed it, so the
13	 * ordering stays stable and strictly increasing for the life of the run.
14	 */
15	@Component
16	public class AuditSequence {
17	
18	    private final AtomicLong counter = new AtomicLong();
19	
20	    /** The next sequence number; strictly greater than every value previously returned. */
21	    public long next() {
22	        return this.counter.incrementAndGet();
23	    }
24	}
