package org.springframework.samples.petclinic.model;

/**
 * Computes the Luhn check digit over the decimal digits contained in a string,
 * ignoring any non-digit characters. Used to derive an owner's check digit from its
 * customer code.
 */
public final class Luhn {

    private Luhn() {
    }

    /**
     * The Luhn check digit (0-9) over the digits contained in {@code value}; non-digit
     * characters are ignored and a {@code null} value is treated as containing no digits.
     */
    public static int checkDigit(String value) {
        if (value == null) {
            return 0;
        }
        int sum = 0;
        boolean doubling = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int digit = c - '0';
            if (doubling) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            sum += digit;
            doubling = !doubling;
        }
        return (10 - (sum % 10)) % 10;
    }
}

package org.springframework.samples.petclinic.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Computes the SHA-256 digest of a string as hexadecimal. Shared by the derived identities that
 * hash owner attributes: the customer code and household id use the upper-case {@link #hex} form,
 * the identity key the lower-case {@link #lowerHex} form.
 */
public final class Sha256 {

    private Sha256() {
    }

    /** The full upper-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    public static String hex(String value) {
        return digestHex(value, "%02X");
    }

    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value} (64 characters). */
    public static String lowerHex(String value) {
        return digestHex(value, "%02x");
    }

    private static String digestHex(String value, String byteFormat) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(String.format(byteFormat, b));
        }
        return hex.toString();
    }
}

